@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

/* Not inherited, so sizes never leak into nested skeletons. */
@property --skeleton-width {
  syntax: "*";
  inherits: false;
}

@property --skeleton-height {
  syntax: "*";
  inherits: false;
}

@property --skeleton-size {
  syntax: "*";
  inherits: false;
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  /* One element per bone, one background layer per bone. The sheen is a soft
     diagonal gradient fixed to the viewport (background-attachment: fixed) and
     every bone runs on one clock (syncSweep), so a single band of light crosses
     the whole layout and each bone lights up as it passes. The image is three
     viewports wide, so the band leaves the screen and rests between passes. */
  .bone {
    --skeleton-sheen: light-dark(
      color-mix(in oklch, var(--ui-surface) 62%, transparent),
      color-mix(in oklch, var(--ui-foreground) 9%, transparent)
    );

    display: block;
    max-width: 100%;
    background-color: var(--ui-fill-strong);
    /* Eased stops, so the band has no edges: light gathers and fades. */
    background-image: linear-gradient(
      110deg,
      transparent 42.5%,
      color-mix(in oklch, var(--skeleton-sheen) 22%, transparent) 45.5%,
      color-mix(in oklch, var(--skeleton-sheen) 62%, transparent) 48%,
      var(--skeleton-sheen) 50%,
      color-mix(in oklch, var(--skeleton-sheen) 62%, transparent) 52%,
      color-mix(in oklch, var(--skeleton-sheen) 22%, transparent) 54.5%,
      transparent 57.5%
    );
    background-size: 300% 100%;
    background-repeat: no-repeat;
    background-attachment: fixed;
    animation: skeleton-sweep calc(var(--ui-dur-sweep) * 2) linear infinite;
    pointer-events: none;
    user-select: none;
  }

  :is([dir="rtl"]) .bone {
    animation-direction: reverse;
  }

  @keyframes skeleton-sweep {
    from {
      background-position: 100% 0;
    }
    to {
      background-position: 0 0;
    }
  }

  .block {
    width: var(--skeleton-width, 100%);
    height: var(--skeleton-height, var(--ui-space-4));
    border-radius: var(--ui-radius-sm);
  }

  .block[data-radius="md"] {
    border-radius: var(--ui-radius-md);
  }

  .block[data-radius="lg"] {
    border-radius: var(--ui-radius-lg);
  }

  .block[data-radius="full"] {
    border-radius: var(--ui-radius-full);
  }

  .circle {
    flex-shrink: 0;
    width: var(--skeleton-size);
    height: var(--skeleton-size);
    border-radius: var(--ui-radius-full);
  }

  /* Text */

  .text {
    display: block;
    width: var(--skeleton-width, 100%);
    max-width: 100%;
  }

  .text[data-size="sm"] {
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .text[data-size="md"] {
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
  }

  .text[data-size="2xl"] {
    font-size: var(--ui-text-2xl);
    line-height: var(--ui-leading-2xl);
  }

  /* One inline bar per line, each the full width so the next one wraps. It's
     shorter than the line, so the strut sets the line height, as for text. */
  .bar {
    display: inline-block;
    vertical-align: baseline;
    width: 100%;
    height: 0.7em;
    height: 1cap;
    border-radius: var(--ui-radius-full);
  }

  .bar:last-child:not(:only-child) {
    width: var(--skeleton-last, 60%);
  }

  /* Group */

  .group {
    display: grid;
    min-width: 0;
  }

  .fallback,
  .content {
    grid-area: 1 / 1;
    min-width: 0;
  }

  .fallback {
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .fallback[data-shown] {
    opacity: 1;
    transition: opacity var(--ui-dur-base) var(--ui-ease-enter);
  }

  .content[data-enter] {
    animation: skeleton-content-in var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2) backwards;
  }

  @keyframes skeleton-content-in {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .bone {
      background-image: none;
      animation: none;
    }
  }

  /* Forced colors drop background fills; an outline keeps the shapes. */
  @media (forced-colors: active) {
    .bone {
      outline: var(--ui-hairline) solid GrayText;
      outline-offset: calc(var(--ui-hairline) * -1);
    }
  }
}

"use client";

import { useEffect, useState, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import styles from "./skeleton.module.css";

type Length = number | string;

const css = (value: Length | undefined) => (typeof value === "number" ? `${value}px` : value);

/** Puts a late bone on the shared band's clock. */
function syncSweep(el: HTMLElement | null) {
  if (!el || typeof el.getAnimations !== "function") return;
  for (const animation of el.getAnimations()) animation.startTime = 0;
}

type SkeletonProps = Omit<ComponentProps<"span">, "children" | "ref"> & {
  /** Numbers are px. Defaults to full width. */
  width?: Length;
  /** Defaults to 16px. Numbers are px. */
  height?: Length;
  /** `sm` (default), `md`, `lg` or `full`. */
  radius?: "sm" | "md" | "lg" | "full";
};

/** A block standing in for something with a known size. */
export function Skeleton({ width, height, radius = "sm", className, style, ...props }: SkeletonProps) {
  return (
    <span
      ref={syncSweep}
      aria-hidden="true"
      data-radius={radius}
      className={className ? `${styles.bone} ${styles.block} ${className}` : `${styles.bone} ${styles.block}`}
      style={{ "--skeleton-width": css(width), "--skeleton-height": css(height), ...style } as CSSProperties}
      {...props}
    />
  );
}

type SkeletonCircleProps = Omit<ComponentProps<"span">, "children" | "ref"> & {
  /** Diameter. Defaults to 40px. */
  size?: Length;
};

/** A circle standing in for an avatar. */
export function SkeletonCircle({ size = 40, className, style, ...props }: SkeletonCircleProps) {
  return (
    <span
      ref={syncSweep}
      aria-hidden="true"
      className={className ? `${styles.bone} ${styles.circle} ${className}` : `${styles.bone} ${styles.circle}`}
      style={{ "--skeleton-size": css(size), ...style } as CSSProperties}
      {...props}
    />
  );
}

type SkeletonTextProps = Omit<ComponentProps<"span">, "children" | "ref"> & {
  lines?: number;
  /** Width of the whole block, e.g. `"9em"`. */
  width?: Length;
  /** Width of the last of several lines. Defaults to 60%. */
  lastLineWidth?: Length;
  /** Type step. Omit to inherit from the parent, the surest match. */
  size?: "sm" | "md" | "2xl";
};

/** Lines standing in for text, as tall as the real lines. */
export function SkeletonText({
  lines = 1,
  width,
  lastLineWidth = "60%",
  size,
  className,
  style,
  ...props
}: SkeletonTextProps) {
  const count = Number.isFinite(lines) ? Math.max(1, Math.round(lines)) : 1;
  return (
    <span
      aria-hidden="true"
      data-size={size}
      className={className ? `${styles.text} ${className}` : styles.text}
      style={{ "--skeleton-width": css(width), "--skeleton-last": css(lastLineWidth), ...style } as CSSProperties}
      {...props}
    >
      {Array.from({ length: count }, (_, i) => (
        <span key={i} ref={syncSweep} className={`${styles.bone} ${styles.bar}`} />
      ))}
    </span>
  );
}

/** True once `loading` has lasted `delay` ms. */
export function useLoadingDelay(loading: boolean, delay = 300) {
  const [late, setLate] = useState(false);
  useEffect(() => {
    if (!loading) return;
    const timer = window.setTimeout(() => setLate(true), delay);
    return () => {
      window.clearTimeout(timer);
      setLate(false);
    };
  }, [loading, delay]);
  return loading && late;
}

// Drops the skeleton anyway in case the entrance animation never runs.
const ENTER_BACKSTOP = 1000;

type SkeletonGroupProps = Omit<ComponentProps<"div">, "children"> & {
  /** While true the skeleton holds the place. */
  loading: boolean;
  fallback: ReactNode;
  children?: ReactNode;
  /** Announced once the wait passes `delay`. */
  label?: string;
  /** Ms before the skeleton shows. Defaults to 300. */
  delay?: number;
};

/** Holds the place of content that is on its way. */
export function SkeletonGroup({
  loading,
  fallback,
  children,
  label = "Loading…",
  delay = 300,
  className,
  ...props
}: SkeletonGroupProps) {
  const late = useLoadingDelay(loading, delay);

  const [kept, setKept] = useState(loading);
  if (loading && !kept) setKept(true);
  const swapping = kept && !loading;

  useEffect(() => {
    if (!swapping) return;
    const timer = window.setTimeout(() => setKept(false), ENTER_BACKSTOP);
    return () => window.clearTimeout(timer);
  }, [swapping]);

  return (
    <>
      <div
        aria-busy={loading || undefined}
        className={className ? `${styles.group} ${className}` : styles.group}
        {...props}
      >
        {kept && (
          <div className={styles.fallback} aria-hidden="true" data-shown={late || undefined}>
            {fallback}
          </div>
        )}
        {!loading && (
          <div
            className={styles.content}
            data-enter={swapping || undefined}
            onAnimationEnd={(event) => {
              if (event.target === event.currentTarget) setKept(false);
            }}
          >
            {children}
          </div>
        )}
      </div>
      {/* Outside aria-busy, which screen readers may hold back. */}
      <span role="status" className={styles.srOnly}>
        {late ? label : ""}
      </span>
    </>
  );
}
